// Parameter (ALLY 38, Talent-Bereich): nur die Sitzung für die Datenbank (64 Hex-Zeichen, sonst leer = nicht angemeldet). Die Talent-ID kommt in der Datenbank
// ausschließlich aus der Sitzung; Parameter aus der Adresse werden nicht verwendet.
// Migration 67: to = geöffnete Freigabe (Ziffern), tp = Unterordner darin; nur für die Ordnerliste über SPEICHER 1, geprüft in der Datenbank.
// Migration 200 (Fehler Nr. 40, Stefan 02.11.2026): Zeitraum wie im Talent-Profil (zeitraum, von, bis; prüft talents_zeitraum) und Seite des Contents
// (?p=content:n) für talent_ui_kacheln; keine Talent-ID.
const E = $input.first().json;
const P = E.parameter || {};
const tp = String(P.tp ?? '').trim();
const ordner = { id: /^[0-9]{1,12}$/.test(String(P.to || '')) ? String(P.to) : '', pfad: tp.length <= 200 && !/[\x00-\x1f\x7f]/.test(tp) ? tp.replace(/\/+$/, '') : '' };
const f = {};
if (/^(7tage|28tage|monat|vormonat|frei)$/.test(String(P.zeitraum || ''))) f.zeitraum = String(P.zeitraum);
for (const k of ['von', 'bis']) if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(P[k] || ''))) f[k] = String(P[k]);
f.seite = String(Math.min(500, Math.max(1, Number((E.seiten || {}).content) || 1)));
return [{ json: { ordner, werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', JSON.stringify(f)] } }];

// Talent-Bereich (ALLY 38, BA7, Stefan 20.10.2026): Ansicht mit der Rolle Talent. Kein Knopf „Chat öffnen“, nur der Chat-Anmeldename. Keine Honorare und Budgets.
// Liefert nur die Seitenbeschreibung (JSON); Daten nur aus „Daten laden“ (talent_ui_daten, talent_ui_kacheln u. a.; Talent-ID immer aus der Sitzung).
// Migration 200 (Fehler Nr. 40, Stefan 02.11.2026 16:14/16:17/16:44/18:22, Entscheidungen 18:41; Konzept Talent-Bereich): Aufbau wie die Talent-Profilseite (ALLY 25):
// Kopf (Hallo, Ansprechperson), Zeitraum, vier Zahlen (Follower, Reichweite, Aufrufe, Interaktionen), darunter Kacheln mit „Anzeigen“ (Regel talent-bereich der
// Web-App, aufbau.ts). Performance (Verlauf je Tag, Audience kurz, Top-Content), Audience, Content (eigene Beiträge) aller eigenen Accounts und die vier Zahlen
// immer (Stefan 03.11.2026 09:47, unabhängig vom Häkchen „Zahlen“). Korrektur 09:23: Freigabe je Eintrag nur für Themen des Managers – Strategie und
// Kommunikation, Reports, Kampagnen (mit ihren Dateien), Notizen, Mediakit des Managers; manuell erfasste Werte immer (09:48); eine solche Kachel ohne freigegebenen Eintrag erscheint nicht. Aufgaben, Termine und Erinnerungen
// („Senden an“), Verbindungen (Verbinden, Erneuern, Trennen), Briefing, Kalender-Abo, Zahlen-Upload, Ally-Chat und Ordner wie bisher; die Häkchen unter „Rolle und
// Ausnahmen“ wirken wie bisher. „Mein Mediakit“: Hochladen wie bisher. Ohne Vergleich mit anderen Talents (Veränderung nur zum eigenen Vorzeitraum).
// BA8 (Migration 63): Kalender-Abo (talent_kalender_abo_ui; tb_kalender_neu, tb_kalender_widerrufen). Migration 64: Zahlen per Screenshot nur mit Freigabe (zahlen_upload).
// Migration 67: „Deine Ordner“ (speicher_talent_ordner_ui; to, tp; Liste über SPEICHER 1; Dateien über die interne Seite „datei“).
// BA9 (Migration 68): „Ally-Chat“ (talent_chat_selbst_ui; tb_chat_passwort; Kontingent ohne Beträge). Migration 196: „Mein Mediakit“ (talents_mediakit_selbst_ui).
const E = $('Start').first().json;
const DL = $('Daten laden').first().json || {};
const D = DL.d || {};
const KD = DL.kd && DL.kd.ok === true ? DL.kd : null;
const ZA = !!KD;   // Zahlen, Performance, Audience, Content immer (Stefan 03.11.2026 09:47)
const KAB = DL.k || {};
const OT = DL.o || {};
const CS = DL.c && DL.c.ok === true && DL.c.an === true ? DL.c : null;
const lief = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const OL = lief('Ordner lesen (SPEICHER 1)') ? ($('Ordner lesen (SPEICHER 1)').first().json || null) : null;
const OPZ = (lief('Parameter') ? $('Parameter').first().json.ordner : null) || {};
const F = E.funktion || {};
const istA = x => Array.isArray(x) ? x : [];
const s = v => String(v ?? '');
if (D.ok !== true) {
  return [{ json: { inhalt: { seite: { schluessel: 'talent-bereich', art: 'funktion', titel: s(F.name || 'Dein Bereich') },
    bloecke: [{ typ: 'text', ton: 'warn', text: 'Dein Bereich konnte gerade nicht geladen werden. Bitte die Seite neu laden.' }] } } }];
}
const AP = istA(D.ansprechpersonen).map(s).filter(Boolean);
const beschreibung = (D.firma ? 'Dein Bereich bei ' + s(D.firma) + '.' : 'Dein Bereich.')
  + (AP.length ? ' ' + (AP.length === 1 ? 'Deine Ansprechperson: ' : 'Deine Ansprechpersonen: ') + AP.join(', ') : '');
const kopf = { schluessel: 'talent-bereich', art: 'funktion', titel: 'Hallo ' + s(D.name || ''), beschreibung };
const abschnitte = [], fenster = [];
const link = (art, id) => ({ seite: 'link', parameter: { art, id: String(id) } });
const hier = anker => ({ seite: 'talent-bereich', anker });
const wt = w => w && typeof w === 'object' && w.text !== undefined && w.text !== null && w.text !== '' ? s(w.text) : '–';
const RI = r => ['hoch', 'runter', 'gleich'].includes(r) ? r : 'gleich';
const zahl = x => { const v = Number(x); return x !== null && x !== undefined && isFinite(v) ? String(Math.round(Math.abs(v))).replace(/\B(?=(\d{3})+(?!\d))/g, '.').replace(/^/, v < 0 ? '−' : '') : '–'; };
const tab = (id, titel, spalten, zeilen, leer) => ({ typ: 'tabelle', id, titel, spalten: spalten.map(x => ({ schluessel: x[0], titel: x[1] })), zeilen,
  sortierung: {}, seite: 1, je_seite: Math.max(1, zeilen.length), gesamt: zeilen.length, leer });

// ---------- Kopf: Zeitraum und vier Zahlen (wie das Talent-Profil, nur eigene Zahlen) ----------
const zr = (KD && KD.zeitraum) || {}, F0 = (KD && KD.filter) || {};
if (ZA) {
  kopf.filter = { id: 'zeitraum', label: 'Zeitraum', felder: [{ typ: 'auswahl', name: 'zeitraum', label: 'Zeitraum', ausklappliste: true, wert: s(F0.zeitraum || '28tage'),
    optionen: istA(KD.zeitraeume).map(z => ({ wert: s(z.schluessel), text: s(z.name) })) }].concat(F0.zeitraum === 'frei' ? [
    { typ: 'datum', name: 'von', label: 'Von', wert: s(F0.von) }, { typ: 'datum', name: 'bis', label: 'Bis', wert: s(F0.bis) }] : []) };
}
const kennzahlen = istA(KD && KD.kennzahlen).map(k => {
  const label = s(k.name || k.schluessel);
  if (k.schluessel === 'follower') { const zu = k.zuwachs || {};
    return Object.assign({ label, wert: wt(k) }, zu.text ? { trend: { text: s(zu.text) + ' im Zeitraum', richtung: Number(zu.wert) > 0 ? 'hoch' : Number(zu.wert) < 0 ? 'runter' : 'gleich' } } : {}); }
  const v = k.veraenderung || {}, vo = k.vorher && k.vorher.wert !== null && k.vorher.wert !== undefined ? 'vorher ' + wt(k.vorher) : '';
  return Object.assign({ label, wert: wt(k), neben: vo }, v.text && v.text !== '–' ? { trend: { text: s(v.text), richtung: RI(v.richtung) } } : {});
});
const nm = Number(KD && KD.manuell) || 0;
const ueberblick = ZA ? { kennzahlen, unter: [zr.text, zr.vor_text, KD.datenstand].filter(Boolean).map(s).join(' · '),
  info: ['Zahlen deiner verbundenen Accounts' + (nm > 0 ? ' und ' + nm + (nm === 1 ? ' bestätigter manueller Wert' : ' bestätigte manuelle Werte') : '') + '. Verglichen wird nur mit deinem eigenen Vorzeitraum.'] } : undefined;

// ---------- Performance (immer): Verlauf je Tag, Audience kurz, Top-Content ----------
const KN = { reichweite: 'Reichweite', aufrufe: 'Aufrufe', interaktionen: 'Interaktionen' };
const ZG = istA(KD && KD.zielgruppe);
const balken = (g, bid, max) => { const EA = istA(g.eintraege), EI = max ? EA.slice(0, max) : EA, m = Math.max(0, ...EI.map(e => Number(e.anteil) || 0));
  const weitere = (Number(g.weitere) || 0) + (EA.length - EI.length);
  const b = [Object.assign(bid ? { id: bid } : {}, { typ: 'liste', balken: true, leer: 'Keine Angaben.', eintraege: EI.map(e => ({ text: s(e.name || e.schluessel), fortschritt: m > 0 ? Math.round((Number(e.anteil) || 0) / m * 100) : 0, label: s(e.anteil_text || e.text) })) })];
  if (weitere > 0) b.push({ typ: 'text', ton: 'grau', text: 'und ' + weitere + ' weitere' });
  return b; };
const gTitel = (g, mitPlattform) => [s(g.name), mitPlattform ? s(g.plattform_name) : '', g.stand ? 'Stand ' + s(g.stand) : ''].filter(Boolean).join(' · ');
const karte = b => Object.assign({ bild: s(b.vorschau_url), bild_alt: [b.art_name || 'Beitrag', b.erstellt ? 'vom ' + b.erstellt : '', b.konto ? 'von ' + b.konto : ''].filter(Boolean).join(' '),
  art: s(b.art_name || 'Beitrag'), titel: [b.art_name, b.erstellt].filter(Boolean).map(s).join(' · '), unter: [b.plattform_name, b.konto].filter(Boolean).map(s).join(' '),
  zahlen: b.hat_zahlen === false ? [] : [['Reichweite', b.reichweite], ['Aufrufe', b.aufrufe], ['Interaktionen', b.interaktionen]].concat(b.interaktionsrate && b.interaktionsrate.text ? [['Rate', b.interaktionsrate]] : [])
    .map(x => ({ label: x[0], wert: wt(x[1]) })), hinweis: s(b.hinweis || 'Noch keine Zahlen für diesen Beitrag.') },
  /^[0-9]{1,15}$/.test(s(b.id)) && /^https:\/\//.test(s(b.link)) ? { ziel: link('b', b.id), ziel_text: 'Beitrag öffnen', ziel_label: s(b.art_name || 'Beitrag') + ' vom ' + s(b.erstellt) + ' auf ' + s(b.plattform_name || 'der Plattform') + ' öffnen' } : {});
if (KD) {
 if (ZA) {
  const vl = KD.verlauf || {}, kn = KN[vl.kennzahl] ? vl.kennzahl : 'reichweite';
  const tage = istA(vl.tage).map(t => ({ datum: s(t.datum || t.tag), wert: t[kn] === null || t[kn] === undefined || !isFinite(Number(t[kn])) ? null : Number(t[kn]) }));
  const perf = [{ typ: 'unterueberschrift', text: KN[kn] + ' je Tag', info: [s(zr.text)].filter(Boolean) }];
  if (vl.hat_daten === true && tage.some(t => t.wert !== null)) perf.push({ typ: 'grafik', art: 'saeulen', beschreibung: KN[kn] + ' je Tag, ' + s(zr.text), werte: tage.map(t => Number(t.wert) || 0),
    tage: tage.map(t => ({ datum: t.datum, wert: t.wert, text: t.wert === null ? '' : zahl(t.wert), kurz: t.wert === null ? '' : zahl(t.wert) })) });
  else perf.push({ typ: 'text', ton: 'grau', text: Number(KD.konten) > 0 ? 'Für diesen Zeitraum liegen keine Zahlen vor.' : 'Noch keine Zahlen. Sobald ein Account verbunden ist, holt Ally die Zahlen jede Nacht.' });
  const g0 = ZG[0];
  if (g0) perf.push({ typ: 'unterueberschrift', text: 'Audience · ' + gTitel(g0, false) }, ...balken(g0, null, 10),
    { typ: 'aktion', text: 'Audience ansehen', art: 'link', kachel: 'audience', ziel: hier('a-audience') });
  const BB = istA(KD.beste).slice(0, 3);
  perf.push({ typ: 'unterueberschrift', text: 'Top-Content', info: BB.length ? ['Deine Beiträge mit der höchsten Reichweite im Zeitraum.'] : undefined });
  if (BB.length) perf.push({ typ: 'galerie', id: 'top', titel: 'Top-Content', bild_leer: 'Keine Vorschau', karten: BB.map(karte) });
  else perf.push({ typ: 'text', ton: 'grau', text: 'Keine Beiträge in diesem Zeitraum.' });
  const CA = Number((KD.content || {}).anzahl) || 0;
  if (CA) perf.push({ typ: 'aktion', text: 'Gesamten Content anzeigen (' + CA + ')', art: 'link', kachel: 'content', ziel: hier('a-content') });
  if (KD.datenstand) perf.push({ typ: 'text', ton: 'grau', text: s(KD.datenstand) });
  abschnitte.push({ id: 'performance', titel: 'Performance', zahl: s(zr.name || ''), offen_standard: true, inhalt: perf });

  // ---------- Audience (immer): Kategorie und Kanal mehrfach wie im Talent-Profil (Baustein „vergleich“) ----------
  const ART = { follower_demographics: 'Follower', engaged_audience_demographics: 'Interagierende Konten', viewer_demographics: 'Zuschauer' };
  const KAT = { age: 'Alter', gender: 'Geschlecht', country: 'Land', city: 'Stadt' }, KO = ['age', 'gender', 'country', 'city'];
  const katVon = g => s(g.aufteilung) || s(g.art);
  const reiheVon = g => s(g.kanal_id) + ':' + s(g.gruppe);
  const rang = k => KO.includes(k) ? KO.indexOf(k) : KO.length;
  const kats = [...new Set(ZG.map(katVon))].sort((a, b) => rang(a) - rang(b));
  const reihen = [...new Set(ZG.map(reiheVon))];
  const mehrere = ZG.some(x => x.plattform !== (ZG[0] || {}).plattform);
  const reiheText = r => { const g = ZG.find(x => reiheVon(x) === r) || {};
    const zweiAccounts = new Set(ZG.filter(x => x.plattform === g.plattform).map(x => s(x.kanal_id))).size > 1;
    const zweiArten = new Set(ZG.filter(x => s(x.kanal_id) === s(g.kanal_id)).map(x => s(x.gruppe))).size > 1;
    return [s(g.plattform_name), zweiAccounts ? s(g.konto || g.kanal_name || '') : '', zweiArten ? s(ART[g.gruppe] || g.gruppe) : ''].filter(Boolean).join(' · '); };
  const katText = k => KAT[k] || s(((ZG.find(x => katVon(x) === k) || {}).name || k).split(' nach ').pop());
  const zt = (n, eins, mehr) => n + ' ' + (n === 1 ? eins : mehr);
  const hinweis = 'Instagram zeigt die Audience erst ab 100 Followern.';
  abschnitte.push({ id: 'audience', titel: 'Audience', offen_standard: false, zahl: ZG.length ? zt(kats.length, 'Kategorie', 'Kategorien') + ' · ' + zt(reihen.length, 'Kanal', 'Kanäle') : '',
    info: ZG.length ? ['Kategorie und Kanal sind mehrfach wählbar; je Kategorie eine Grafik. Je Kanal und Kategorie höchstens 10 Einträge.', hinweis] : [hinweis],
    inhalt: ZG.length ? [{ typ: 'vergleich', id: 'audience', hoechstens: 10, leer: 'Bitte mindestens eine Kategorie und einen Kanal wählen.',
      kategorie: { typ: 'mehrfach', liste: true, name: 'kategorie', label: 'Kategorie', platzhalter: 'Keine Kategorie', einheit: 'Kategorien', wert: [katVon(ZG[0])],
        optionen: kats.map(k => Object.assign({ wert: k, text: katText(k) }, k === 'age' ? { ordnung: 'schluessel' } : {})) },
      reihe: { typ: 'mehrfach', liste: true, name: 'kanal', label: 'Kanal', platzhalter: 'Kein Kanal', einheit: 'Kanäle', wert: [reiheVon(ZG[0])],
        optionen: reihen.map(r => ({ wert: r, text: reiheText(r) })) },
      daten: ZG.map((g, i) => ({ kategorie: katVon(g), reihe: reiheVon(g), name: reiheText(reiheVon(g)), titel: gTitel(g, mehrere), stand: s(g.stand),
        inhalt: balken(g, 'zg-' + i),
        werte: istA(g.eintraege).map(e => ({ schluessel: s(e.schluessel || e.name), text: s(e.name || e.schluessel), wert: Number(e.anteil) || 0, wert_text: s(e.anteil_text || e.text) })) })) }]
      : [{ typ: 'text', ton: 'grau', text: 'Noch keine Angaben zur Audience. ' + hinweis }] });

  // ---------- Content (immer): eigene Beiträge, je Seite 20 ----------
  const C = KD.content || {};
  abschnitte.push({ id: 'content', titel: 'Content', zahl: (Number(C.anzahl) || 0) + ((Number(C.anzahl) || 0) === 1 ? ' Beitrag' : ' Beiträge'), offen_standard: false,
    inhalt: [{ typ: 'galerie', id: 'content', titel: 'Content', bild_leer: 'Keine Vorschau', karten: istA(C.beitraege).map(karte), seite: Number(C.seite) || 1,
      je_seite: Number(C.je_seite) || 20, gesamt: Number(C.anzahl) || 0, leer: 'Noch keine Beiträge.' }] });
 }

  // ---------- Strategie und Kommunikation (nur freigegebene Content-Strategien) ----------
  const ST = istA(KD.strategie);
  if (ST.length) {
    const inhalt = [];
    ST.forEach((c, i) => {
      inhalt.push({ typ: 'unterueberschrift', text: [s(c.art_text || 'Content-Strategie'), s(c.status_text)].filter(Boolean).join(' · ') },
        { typ: 'paare', eintraege: [['Positionierung', c.positionierung], ['Zielgruppe', c.zielgruppe]].filter(x => s(x[1]).trim()).map(x => ({ label: x[0], wert: s(x[1]) })) });
      const K = istA(c.kanaele), PL = istA(c.themenplan), ZL = istA(c.ziele);
      if (K.length) inhalt.push(tab('konzept-kanaele-' + i, 'Format-Mix je Kanal', [['kanal', 'Kanal'], ['bpw', 'Beiträge pro Woche'], ['hinweis', 'Hinweis']],
        K.map(k => ({ zellen: { kanal: { text: s(k.plattform_name || k.plattform), fett: true }, bpw: s(k.beitraege_pro_woche ?? '–').replace('.', ','), hinweis: s(k.hinweis || '–') } })), 'Keine Kanäle.'));
      if (PL.length) inhalt.push(tab('konzept-plan-' + i, 'Themenplan', [['thema', 'Woche und Thema'], ['format', 'Format'], ['idee', 'Idee']],
        PL.map(p => ({ zellen: { thema: { text: 'Woche ' + s(p.woche) + ': ' + s(p.thema), fett: true }, format: s(p.format_name || '–'), idee: s(p.idee || '–') } })), 'Kein Themenplan.'));
      if (ZL.length) inhalt.push(tab('konzept-ziele-' + i, 'Ziele', [['ziel', 'Kennzahl'], ['soll', 'Ziel'], ['ist', 'Ist'], ['stand', 'Stand']],
        ZL.map(z => ({ zellen: { ziel: { text: s(z.kennzahl_name), fett: true, neben: [z.plattform_name, z.zeitraum_text].filter(Boolean).map(s).join(' · ') }, soll: s(z.soll_text || '–'),
          ist: { text: s(z.ist_text || '–'), neben: s(z.stand_text || '') }, stand: s(z.status_text || '–') } })), 'Keine Ziele.'));
    });
    abschnitte.push({ id: 'strategie', titel: 'Strategie und Kommunikation', zahl: String(ST.length), offen_standard: false,
      info: 'Content-Strategien, die dein Manager oder deine Managerin mit dir teilt.', inhalt });
  }

  // ---------- Reports (nur freigegebene Reports über dich) ----------
  const RP = istA(KD.berichte);
  if (RP.length) abschnitte.push({ id: 'reports', titel: 'Reports', zahl: String(RP.length), offen_standard: false, info: 'Reports, die dein Manager oder deine Managerin mit dir teilt.',
    inhalt: [tab('reports', 'Reports', [['titel', 'Report'], ['zeitraum', 'Zeitraum'], ['erstellt', 'Erstellt'], ['datei', 'Datei']],
      RP.map(r => ({ zellen: { titel: { text: s(r.titel), fett: true }, zeitraum: s(r.zeitraum_text || '–'), erstellt: s(r.erstellt_text || '–'),
        datei: r.fertig === true ? { text: 'Herunterladen', ziel: { seite: 'datei', parameter: { tr: s(r.id) } } } : 'noch nicht fertig' } })), 'Keine Reports.')] });
}

// ---------- Dein Briefing (und Chat-Anmeldename, ohne Knopf „Chat öffnen“) ----------
const chat = D.chat_benutzer && !CS ? [{ typ: 'paare', eintraege: [{ label: 'Chat-Anmeldename', wert: s(D.chat_benutzer) }] }] : [];
const chatInfo = 'Mit diesem Anmeldenamen meldest du dich im Chat an (App Element).';
if (D.briefing) {
  const B = D.briefing;
  abschnitte.push({ id: 'briefing', titel: 'Dein Briefing', zahl: B.am ? s(B.am) : '', offen_standard: true, info: chat.length ? chatInfo : undefined,
    inhalt: [B.text ? { typ: 'text', text: s(B.text) } : { typ: 'text', ton: 'grau', text: 'Noch kein Briefing.' }].concat(chat) });
} else if (chat.length) abschnitte.push({ id: 'chat', titel: 'Chat', offen_standard: true, info: chatInfo, inhalt: chat });

// ---------- Kampagnen (nur vom Manager freigegebene, dazu die Häkchen Kampagnen bzw. Dateien): Briefing der Marke und Dateien der Kampagne ----------
const KA = istA(D.kampagnen), DA = istA(D.dateien);
if (KA.length || DA.length) {
  const inhalt = [];
  for (const k of KA) {
    const paare = [['Zeitraum', k.zeitraum], ['Ziel', k.briefing_ziel], ['Kernbotschaft', k.kernbotschaft], ['Dos', k.dos], ["Don'ts", k.donts], ['Werbekennzeichnung', k.werbekennzeichnung],
      ['Hashtags', istA(k.hashtags).join(' ')], ['Accounts der Marke', istA(k.marken_konten).join(', ')]].filter(x => s(x[1]).trim() !== '').map(x => ({ label: x[0], wert: s(x[1]) }));
    inhalt.push({ typ: 'unterueberschrift', text: s(k.titel) }, { typ: 'paare', eintraege: paare });
  }
  if (DA.length) inhalt.push({ typ: 'unterueberschrift', text: 'Dateien' }, { typ: 'liste', leer: 'Keine Dateien.',
    eintraege: DA.map(d => ({ fett: s(d.titel), text: s(d.kampagne), neben: s(d.dienst_text), ziel: link('kl', d.id), ziel_text: 'Öffnen' })) });
  abschnitte.push({ id: 'kampagnen', titel: 'Kampagnen', zahl: String(KA.length || DA.length), offen_standard: false, inhalt });
}

// ---------- Aufgaben, Termine und Erinnerungen (wie bisher: „Senden an“ und die Häkchen Aufgaben bzw. Termine; Deliverables mit „sichtbar für Talent“) ----------
const entwurfFenster = (id, titel, neu) => {
  if (fenster.some(f => f.id === 'entwurf-' + id)) return;
  fenster.push({ id: 'entwurf-' + id, art: 'dialog', titel: neu ? 'Entwurf neu einreichen' : 'Entwurf einreichen', untertitel: titel, inhalt: [
    { typ: 'hinweis', text: 'Lade den Entwurf bei deinem Cloud-Dienst hoch (z. B. Google Drive, Dropbox oder OneDrive) und füge hier den Link zum Teilen ein. Die Datei selbst wird hier nicht gespeichert.' },
